node -e "
const input = process.env.CLAUDE_TOOL_INPUT || '';
const cmd = (() => { try { return JSON.parse(input).command || ''; } catch { return input; } })();
const banned = [
  { pattern: /--no-verify/, msg: 'constitution §8.4: --no-verify está prohibido excepto en hotfix documentados' },
  { pattern: /push.*--force.*main|push.*-f.*main/, msg: 'constitution §8.4: force-push a main está prohibido' },
  { pattern: /git\s+push\s+--force(?!.*hotfix)/, msg: 'constitution §8.4: usa --force-with-lease o documenta el hotfix' }
];
for (const { pattern, msg } of banned) {
  if (pattern.test(cmd)) {
    process.stderr.write('\x1b[31m[HOOK BLOCKED]\x1b[0m ' + msg + '\n');
    process.exit(2);
  }
}
process.exit(0);"

node -e "
const input = process.env.CLAUDE_TOOL_INPUT || '';
let filePath = '';
try { filePath = JSON.parse(input).file_path || JSON.parse(input).path || ''; } catch {}
if (/\.env($|\.[^.]+$)/.test(filePath) && !filePath.includes('.env.example')) {
  process.stderr.write('\x1b[31m[HOOK BLOCKED]\x1b[0m Editar .env requiere confirmación explícita del usuario (constitution §6)\n');
  process.exit(2);
}
process.exit(0);"

node -e "
const input = process.env.CLAUDE_TOOL_INPUT || '';
let filePath = '';
try { filePath = JSON.parse(input).file_path || JSON.parse(input).path || ''; } catch {}
if (!filePath) process.exit(0);
const ext = filePath.split('.').pop();
if (['ts','tsx','js','jsx','mjs','cjs','json','css','md'].includes(ext)) {
  const { execSync } = require('child_process');
  try {
    execSync('npx prettier --write \"' + filePath + '\" --log-level=silent', { stdio: 'pipe' });
  } catch {}
}
process.exit(0);"

node -e "
const now = new Date().toISOString();
const { execSync } = require('child_process');
let branch = 'unknown';
try { branch = execSync('git branch --show-current', { stdio: 'pipe' }).toString().trim(); } catch {}
console.log('\x1b[36m[Session ended]\x1b[0m ' + now + ' | branch: ' + branch);
console.log('Recuerda: pnpm release:preflight antes de push a main.');
process.exit(0);"
